CREATE TABLE IF NOT EXISTS "wms_warehouse" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(20) NOT NULL,
    "name" varchar(50) NOT NULL,
    "remark" varchar(255) DEFAULT NULL,
    "sort" int DEFAULT '0',
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS 仓库表';

CREATE TABLE IF NOT EXISTS "wms_merchant" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(20) NOT NULL,
    "name" varchar(60) NOT NULL,
    "type" tinyint NOT NULL,
    "level" varchar(10) DEFAULT NULL,
    "bank_name" varchar(255) DEFAULT NULL,
    "bank_account" varchar(40) DEFAULT NULL,
    "address" varchar(200) DEFAULT NULL,
    "mobile" varchar(13) DEFAULT NULL,
    "telephone" varchar(13) DEFAULT NULL,
    "contact" varchar(30) DEFAULT NULL,
    "email" varchar(50) DEFAULT NULL,
    "remark" varchar(255) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS 往来企业表';

CREATE TABLE IF NOT EXISTS "wms_item_brand" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(20) NOT NULL,
    "name" varchar(30) NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS 商品品牌表';

CREATE TABLE IF NOT EXISTS "wms_item_category" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "parent_id" bigint NOT NULL DEFAULT '0',
    "code" varchar(20) NOT NULL,
    "name" varchar(30) NOT NULL,
    "sort" int DEFAULT '0',
    "status" tinyint NOT NULL DEFAULT '1',
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS 商品分类表';

CREATE TABLE IF NOT EXISTS "wms_item" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(20) DEFAULT NULL,
    "name" varchar(60) NOT NULL,
    "category_id" bigint NOT NULL,
    "unit" varchar(20) DEFAULT NULL,
    "brand_id" bigint DEFAULT NULL,
    "abc_classification" varchar(10) DEFAULT NULL,
    "remark" varchar(255) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS 商品表';

CREATE TABLE IF NOT EXISTS "wms_item_sku" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(255) NOT NULL,
    "item_id" bigint NOT NULL,
    "bar_code" varchar(64) DEFAULT NULL,
    "code" varchar(64) DEFAULT NULL,
    "length" decimal(10, 1) DEFAULT NULL,
    "width" decimal(10, 1) DEFAULT NULL,
    "height" decimal(10, 1) DEFAULT NULL,
    "gross_weight" decimal(10, 3) DEFAULT NULL,
    "net_weight" decimal(10, 3) DEFAULT NULL,
    "cost_price" decimal(16, 2) DEFAULT NULL,
    "selling_price" decimal(16, 2) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS 商品 SKU 表';

CREATE TABLE IF NOT EXISTS "wms_inventory" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "sku_id" bigint NOT NULL,
    "warehouse_id" bigint NOT NULL,
    "area_id" bigint NOT NULL DEFAULT '0',
    "quantity" decimal(20, 2) NOT NULL DEFAULT '0',
    "available_quantity" decimal(20, 4) NOT NULL DEFAULT '0',
    "locked_quantity" decimal(20, 4) NOT NULL DEFAULT '0',
    "frozen_quantity" decimal(20, 4) NOT NULL DEFAULT '0',
    "owner_id" bigint DEFAULT NULL,
    "remark" varchar(255) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_sku_id_warehouse_id" UNIQUE ("sku_id", "warehouse_id")
) COMMENT 'WMS 库存表';

CREATE TABLE IF NOT EXISTS "wms_inventory_history" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "warehouse_id" bigint NOT NULL,
    "area_id" bigint NOT NULL DEFAULT '0',
    "sku_id" bigint NOT NULL,
    "quantity" decimal(20, 2) NOT NULL DEFAULT '0',
    "before_quantity" decimal(20, 2) DEFAULT NULL,
    "after_quantity" decimal(20, 2) DEFAULT NULL,
    "batch_no" varchar(64) DEFAULT NULL,
    "production_date" timestamp DEFAULT NULL,
    "expiration_date" timestamp DEFAULT NULL,
    "price" decimal(16, 2) DEFAULT NULL,
    "total_price" decimal(16, 2) DEFAULT NULL,
    "remark" varchar(255) DEFAULT NULL,
    "order_id" bigint DEFAULT NULL,
    "order_no" varchar(64) DEFAULT NULL,
    "order_type" int DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS 库存流水表';

CREATE TABLE IF NOT EXISTS "wms_receipt_order" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "no" varchar(64) NOT NULL,
    "type" int NOT NULL,
    "order_time" timestamp NOT NULL,
    "status" int NOT NULL DEFAULT '0',
    "biz_order_no" varchar(64) DEFAULT NULL,
    "merchant_id" bigint DEFAULT NULL,
    "remark" varchar(255) DEFAULT NULL,
    "warehouse_id" bigint NOT NULL,
    "area_id" bigint NOT NULL DEFAULT '0',
    "total_quantity" decimal(20, 2) NOT NULL DEFAULT '0',
    "total_price" decimal(16, 2) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS 入库单表';

CREATE TABLE IF NOT EXISTS "wms_receipt_order_detail" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "order_id" bigint NOT NULL,
    "sku_id" bigint NOT NULL,
    "warehouse_id" bigint NOT NULL,
    "area_id" bigint NOT NULL DEFAULT '0',
    "batch_no" varchar(64) DEFAULT NULL,
    "production_date" timestamp DEFAULT NULL,
    "expiry_date" timestamp DEFAULT NULL,
    "quantity" decimal(20, 2) NOT NULL DEFAULT '0',
    "price" decimal(16, 2) DEFAULT NULL,
    "total_price" decimal(16, 2) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS 入库单明细表';

CREATE TABLE IF NOT EXISTS "wms_shipment_order" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "no" varchar(64) NOT NULL,
    "type" int NOT NULL,
    "order_time" timestamp NOT NULL,
    "status" int NOT NULL DEFAULT '0',
    "biz_order_no" varchar(64) DEFAULT NULL,
    "merchant_id" bigint DEFAULT NULL,
    "remark" varchar(255) DEFAULT NULL,
    "warehouse_id" bigint NOT NULL,
    "area_id" bigint NOT NULL DEFAULT '0',
    "total_quantity" decimal(20, 2) NOT NULL DEFAULT '0',
    "total_price" decimal(16, 2) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS 出库单表';

CREATE TABLE IF NOT EXISTS "wms_shipment_order_detail" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "order_id" bigint NOT NULL,
    "sku_id" bigint NOT NULL,
    "warehouse_id" bigint NOT NULL,
    "area_id" bigint NOT NULL DEFAULT '0',
    "inventory_detail_id" bigint DEFAULT NULL,
    "batch_no" varchar(64) DEFAULT NULL,
    "production_date" timestamp DEFAULT NULL,
    "expiration_date" timestamp DEFAULT NULL,
    "quantity" decimal(20, 2) NOT NULL DEFAULT '0',
    "price" decimal(16, 2) DEFAULT NULL,
    "total_price" decimal(16, 2) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS 出库单明细表';

CREATE TABLE IF NOT EXISTS "wms_movement_order" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "no" varchar(64) NOT NULL,
    "order_time" timestamp NOT NULL,
    "status" int NOT NULL DEFAULT '0',
    "remark" varchar(255) DEFAULT NULL,
    "source_warehouse_id" bigint NOT NULL,
    "target_warehouse_id" bigint NOT NULL,
    "total_quantity" decimal(20, 2) NOT NULL DEFAULT '0',
    "total_price" decimal(16, 2) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS 移库单表';

CREATE TABLE IF NOT EXISTS "wms_movement_order_detail" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "order_id" bigint NOT NULL,
    "sku_id" bigint NOT NULL,
    "source_warehouse_id" bigint NOT NULL,
    "target_warehouse_id" bigint NOT NULL,
    "inventory_detail_id" bigint DEFAULT NULL,
    "batch_no" varchar(64) DEFAULT NULL,
    "production_date" timestamp DEFAULT NULL,
    "expiration_date" timestamp DEFAULT NULL,
    "quantity" decimal(20, 2) NOT NULL DEFAULT '0',
    "price" decimal(16, 2) DEFAULT NULL,
    "total_price" decimal(16, 2) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS 移库单明细表';

CREATE TABLE IF NOT EXISTS "wms_check_order" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "no" varchar(64) NOT NULL,
    "order_time" timestamp NOT NULL,
    "status" int NOT NULL DEFAULT '0',
    "check_type" int DEFAULT NULL,
    "cycle_days" int DEFAULT NULL,
    "remark" varchar(255) DEFAULT NULL,
    "warehouse_id" bigint NOT NULL,
    "area_id" bigint NOT NULL DEFAULT '0',
    "total_quantity" decimal(20, 2) NOT NULL DEFAULT '0',
    "total_price" decimal(16, 2) DEFAULT NULL,
    "actual_price" decimal(16, 2) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS 盘库单表';

CREATE TABLE IF NOT EXISTS "wms_check_order_detail" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "order_id" bigint NOT NULL,
    "sku_id" bigint NOT NULL,
    "warehouse_id" bigint NOT NULL,
    "area_id" bigint NOT NULL DEFAULT '0',
    "inventory_id" bigint DEFAULT NULL,
    "inventory_detail_id" bigint DEFAULT NULL,
    "batch_no" varchar(64) DEFAULT NULL,
    "production_date" timestamp DEFAULT NULL,
    "expiration_date" timestamp DEFAULT NULL,
    "receipt_time" timestamp DEFAULT NULL,
    "quantity" decimal(20, 2) NOT NULL DEFAULT '0',
    "check_quantity" decimal(20, 2) NOT NULL DEFAULT '0',
    "price" decimal(16, 2) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS 盘库单明细表';

-- ============ 以下为历史缺表补齐（Item C 补测所需，H2 兼容语法） ============

CREATE TABLE IF NOT EXISTS "wms_sn" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "sn" varchar(64) NOT NULL,
    "product_id" bigint NOT NULL,
    "batch_id" bigint DEFAULT NULL,
    "inventory_id" bigint DEFAULT NULL,
    "status" varchar(32) NOT NULL DEFAULT 'GENERATED',
    "warehouse_id" bigint DEFAULT NULL,
    "zone_id" bigint DEFAULT NULL,
    "location_id" bigint DEFAULT NULL,
    "inbound_order_id" bigint DEFAULT NULL,
    "outbound_order_id" bigint DEFAULT NULL,
    "bound_time" timestamp DEFAULT NULL,
    "shipped_time" timestamp DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_sn" UNIQUE ("sn", "tenant_id")
) COMMENT 'WMS 序列号';

CREATE TABLE IF NOT EXISTS "wms_inventory_batch" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "inventory_id" bigint NOT NULL,
    "batch_no" varchar(64) NOT NULL,
    "production_date" date DEFAULT NULL,
    "expiry_date" date DEFAULT NULL,
    "quantity" decimal(20,4) NOT NULL DEFAULT '0',
    "locked_quantity" decimal(20,4) NOT NULL DEFAULT '0',
    "shelf_life_days" int DEFAULT NULL,
    "supplier_batch_no" varchar(64) DEFAULT NULL,
    "status" varchar(20) NOT NULL DEFAULT 'AVAILABLE',
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_inventory_batch" UNIQUE ("inventory_id", "batch_no")
) COMMENT 'WMS 库存批次表';

CREATE TABLE IF NOT EXISTS "wms_dock" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "warehouse_id" bigint NOT NULL,
    "dock_code" varchar(64) NOT NULL,
    "dock_name" varchar(128) NOT NULL,
    "dock_type" tinyint DEFAULT '10',
    "status" tinyint NOT NULL DEFAULT '10',
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_dock_code" UNIQUE ("dock_code", "tenant_id")
) COMMENT 'WMS 月台管理表';

CREATE TABLE IF NOT EXISTS "wms_asn_order" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "no" varchar(64) NOT NULL,
    "supplier_id" bigint DEFAULT NULL,
    "warehouse_id" bigint DEFAULT NULL,
    "dock_id" bigint DEFAULT NULL,
    "expected_arrival_time" timestamp DEFAULT NULL,
    "actual_arrival_time" timestamp DEFAULT NULL,
    "status" tinyint NOT NULL DEFAULT '10',
    "total_quantity" decimal(20,4) DEFAULT '0',
    "total_amount" decimal(20,4) DEFAULT '0',
    "transport_mode" tinyint DEFAULT NULL,
    "carrier_name" varchar(128) DEFAULT NULL,
    "vehicle_no" varchar(32) DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_asn_no" UNIQUE ("no", "tenant_id")
) COMMENT 'WMS ASN 到货通知单表';

CREATE TABLE IF NOT EXISTS "wms_asn_order_detail" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "asn_order_id" bigint NOT NULL,
    "sku_id" bigint NOT NULL,
    "product_name" varchar(256) DEFAULT NULL,
    "expected_quantity" decimal(20,4) NOT NULL DEFAULT '0',
    "received_quantity" decimal(20,4) NOT NULL DEFAULT '0',
    "unit" varchar(32) DEFAULT NULL,
    "lot_number" varchar(64) DEFAULT NULL,
    "production_date" date DEFAULT NULL,
    "expiry_date" date DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS ASN 到货通知单明细表';

CREATE TABLE IF NOT EXISTS "wms_wave_order" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "no" varchar(64) NOT NULL,
    "warehouse_id" bigint NOT NULL,
    "strategy" tinyint NOT NULL,
    "order_time" timestamp NOT NULL,
    "status" tinyint NOT NULL DEFAULT '0',
    "picker" varchar(64) DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "shipment_count" int DEFAULT '0',
    "sku_count" int DEFAULT '0',
    "total_quantity" decimal(20,4) DEFAULT '0',
    "total_price" decimal(20,4) DEFAULT '0',
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_wave_no" UNIQUE ("no")
) COMMENT 'WMS 波次单主表';

CREATE TABLE IF NOT EXISTS "wms_wave_order_detail" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "wave_order_id" bigint NOT NULL,
    "shipment_order_id" bigint NOT NULL,
    "sku_id" bigint NOT NULL,
    "pick_quantity" decimal(20,4) NOT NULL DEFAULT '0',
    "picked_quantity" decimal(20,4) NOT NULL DEFAULT '0',
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'WMS 波次单明细表';
